import { ChartCard } from './chart-card';
import {
  areaPathOf,
  GRID_STEPS,
  linePathOf,
  niceScaleOf,
  pointsOf,
  shareOf,
  VIEW_WIDTH,
} from './chart-math';
import { COMPACT_FORMAT, COUNT_FORMAT, formatCount } from './format';
import { MorphPath } from './morph-path';
import { TRAFFIC_POINTS, type PeriodData } from './period-data';
import { useReading } from './use-reading';

const PLOT_HEIGHT = 176;

const MIDDLE_POINT = Math.floor(TRAFFIC_POINTS / 2);

const LINE_STROKE =
  'fill-none stroke-2 [stroke-linecap:round] [stroke-linejoin:round]';

function gridTopOf(step: number) {
  const share = step / GRID_STEPS;
  return PLOT_HEIGHT - share * PLOT_HEIGHT;
}

function readoutClassOf(isReading: boolean) {
  if (isReading) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

const GRID_STEP_LIST = Array.from(
  { length: GRID_STEPS + 1 },
  (_, step) => step
);

function readingCaptionOf(
  isReading: boolean,
  data: PeriodData,
  label: string,
  current: number,
  previous: number
) {
  if (!isReading) {
    return data.visitsChange;
  }
  return `${label}: ${formatCount(current)} a day, ${formatCount(previous)} before`;
}

type TrafficLineProps = {
  data: PeriodData;
};

export function TrafficLine({ data }: TrafficLineProps) {
  const reading = useReading(TRAFFIC_POINTS, 'point');
  const largest = Math.max(...data.traffic, ...data.previousTraffic);
  const scale = niceScaleOf(largest);
  const currentPoints = pointsOf(data.traffic, scale.max, PLOT_HEIGHT);
  const previousPoints = pointsOf(data.previousTraffic, scale.max, PLOT_HEIGHT);
  const index = reading.shownIndex;
  const current = Math.round(data.traffic[index]);
  const previous = Math.round(data.previousTraffic[index]);
  const label = data.bucketLabels[index];
  const caption = readingCaptionOf(
    reading.isReading,
    data,
    label,
    current,
    previous
  );
  const guideShare = index / (TRAFFIC_POINTS - 1);
  const currentTop = PLOT_HEIGHT - shareOf(current, scale.max) * PLOT_HEIGHT;
  const previousTop = PLOT_HEIGHT - shareOf(previous, scale.max) * PLOT_HEIGHT;
  const spoken = `${label}, ${formatCount(current)} visits a day, ${formatCount(previous)} in the period before`;
  const referenceLabel = `The ${data.months} months before`;

  return (
    <ChartCard
      title='Traffic'
      section='traffic'
      description={
        <p className='text-muted-foreground text-xs'>Average visits per day</p>
      }
    >
      <div className='flex flex-col gap-1'>
        <p className='flex items-baseline gap-1.5'>
          <MotionNumber
            value={data.totalVisits}
            format={COUNT_FORMAT}
            className='text-2xl leading-8 font-semibold'
          />
          <span className='text-muted-foreground text-[13px]'>visits</span>
        </p>
        {!reading.isReading && (
          <Swap swapKey={caption} className='text-muted-foreground text-xs'>
            {caption}
          </Swap>
        )}
        {reading.isReading && (
          <p className='text-muted-foreground text-xs'>{caption}</p>
        )}
      </div>
      <div className='grid grid-cols-[auto_minmax(0,1fr)] gap-x-2'>
        <div
          aria-hidden='true'
          className='relative w-9 shrink-0'
          style={{ height: PLOT_HEIGHT }}
        >
          {GRID_STEP_LIST.map((step) => (
            <span
              key={step}
              className='text-muted-foreground absolute right-0 -translate-y-1/2 text-[11px]'
              style={{ top: gridTopOf(step) }}
            >
              <MotionNumber value={scale.ticks[step]} format={COMPACT_FORMAT} />
            </span>
          ))}
        </div>
        <div
          role='slider'
          tabIndex={0}
          aria-label='Visits per day. The arrow keys read each point'
          aria-orientation='horizontal'
          aria-valuemin={0}
          aria-valuemax={TRAFFIC_POINTS - 1}
          aria-valuenow={index}
          aria-valuetext={spoken}
          className='focus-visible:ring-ring/25 @container relative touch-pan-y rounded-md outline-none focus-visible:ring-[3px]'
          style={{ height: PLOT_HEIGHT }}
          {...reading.handlers}
        >
          {GRID_STEP_LIST.map((step) => (
            <span
              key={step}
              aria-hidden='true'
              className='hairline-t border-border pointer-events-none absolute inset-x-0'
              style={{ top: gridTopOf(step) }}
            />
          ))}
          <svg
            aria-hidden='true'
            viewBox={`0 0 ${VIEW_WIDTH} ${PLOT_HEIGHT}`}
            preserveAspectRatio='none'
            className='pointer-events-none absolute inset-0 size-full overflow-visible'
          >
            <MorphPath
              d={areaPathOf(currentPoints, PLOT_HEIGHT)}
              className='fill-primary/10'
            />
            <MorphPath
              d={linePathOf(previousPoints)}
              className={cn(
                LINE_STROKE,
                'stroke-foreground/40 [stroke-dasharray:4_4]'
              )}
            />
            <MorphPath
              d={linePathOf(currentPoints)}
              className={cn(LINE_STROKE, 'stroke-primary')}
            />
          </svg>
          <div
            aria-hidden='true'
            className={cn(
              'pointer-events-none absolute inset-y-0 left-0 w-0 transition-[opacity,transform] duration-150 ease-(--ease-out-strong)',
              readoutClassOf(reading.isReading)
            )}
            style={{ transform: `translateX(${guideShare * 100}cqw)` }}
          >
            <span className='bg-foreground/15 absolute inset-y-0 w-px -translate-x-1/2' />
            <span
              className='bg-foreground/40 ring-card absolute size-2 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2'
              style={{ top: previousTop }}
            />
            <span
              className='bg-primary ring-card absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2'
              style={{ top: currentTop }}
            />
          </div>
        </div>
        <div
          aria-hidden='true'
          className='text-muted-foreground col-start-2 mt-2 flex h-4 justify-between text-[11px] tabular-nums'
        >
          <Swap swapKey={data.bucketLabels[0]}>{data.bucketLabels[0]}</Swap>
          <Swap swapKey={data.bucketLabels[MIDDLE_POINT]}>
            {data.bucketLabels[MIDDLE_POINT]}
          </Swap>
          <Swap swapKey={data.bucketLabels[TRAFFIC_POINTS - 1]}>
            {data.bucketLabels[TRAFFIC_POINTS - 1]}
          </Swap>
        </div>
      </div>
      <ul className='text-muted-foreground flex flex-wrap items-center gap-x-4 gap-y-1 text-xs'>
        <li className='flex items-center gap-1.5'>
          <span
            aria-hidden='true'
            className='bg-primary h-0.5 w-4 rounded-full'
          />
          This period
        </li>
        <li className='flex items-center gap-1.5'>
          <span
            aria-hidden='true'
            className='border-foreground/40 w-4 border-t-2 border-dashed'
          />
          <Swap swapKey={referenceLabel}>{referenceLabel}</Swap>
        </li>
      </ul>
    </ChartCard>
  );
}

'use client';

import { useState } from 'react';

import { clamp } from './chart-math';
import { rovingTargetOf } from './roving';

/** A line has a point at each edge of its plot; bars have a column each, so a pointer lands on the column under it. */
export type ReadingMode = 'point' | 'column';

function indexAtOf(ratio: number, count: number, mode: ReadingMode) {
  const lastIndex = count - 1;
  if (mode === 'point') {
    return clamp(Math.round(ratio * lastIndex), 0, lastIndex);
  }
  return clamp(Math.floor(ratio * count), 0, lastIndex);
}

/**
 * What a plot reads out: the position under the pointer or the one the arrow keys reached, and the
 * last position when nobody reads. The plot is the one tab stop of its chart.
 */
export function useReading(count: number, mode: ReadingMode) {
  const [reading, setReading] = useState<number | null>(null);
  const lastIndex = Math.max(count - 1, 0);
  const shownIndex = Math.min(reading ?? lastIndex, lastIndex);
  const isReading = reading !== null;

  function readFromPointer(event: React.PointerEvent<HTMLDivElement>) {
    const box = event.currentTarget.getBoundingClientRect();
    const ratio = (event.clientX - box.left) / box.width;
    setReading(indexAtOf(ratio, count, mode));
  }

  function readFromKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      setReading(null);
      return;
    }
    const next = rovingTargetOf(event.key, shownIndex, count);
    if (next === null) {
      return;
    }
    event.preventDefault();
    setReading(next);
  }

  function stopReading() {
    setReading(null);
  }

  return {
    shownIndex,
    isReading,
    handlers: {
      onPointerMove: readFromPointer,
      onPointerLeave: stopReading,
      onKeyDown: readFromKeys,
      onBlur: stopReading,
    },
  };
}

'use client';

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import { ChartCard } from './chart-card';
import {
  campaignOf,
  CAMPAIGNS,
  channelOf,
  TODAY_INDEX,
  WEEK,
  WEEK_RANGE,
  type Campaign,
} from './data';

type ChipStyle = React.CSSProperties & { '--chip': string };

type WeekItem = {
  campaign: Campaign;
  from: number;
  to: number;
  lane: number;
};

type Span = {
  from: number;
  to: number;
};

function spanOf(campaign: Campaign): Span | null {
  const { weekFrom, weekTo } = campaign;
  if (weekFrom === undefined || weekTo === undefined) {
    return null;
  }
  return { from: weekFrom, to: weekTo };
}

/** Each campaign takes the first row where the one before it has ended, so the strip is as short as it can be. */
function itemsOfWeek() {
  const items: WeekItem[] = [];
  const laneEnds: number[] = [];
  const running = CAMPAIGNS.flatMap((campaign) => {
    const span = spanOf(campaign);
    if (span === null) {
      return [];
    }
    return [{ campaign, span }];
  });
  const ordered = running.sort((first, second) => {
    const gap = first.span.from - second.span.from;
    if (gap !== 0) {
      return gap;
    }
    return second.span.to - first.span.to;
  });
  for (const { campaign, span } of ordered) {
    let lane = laneEnds.findIndex((end) => end < span.from);
    if (lane === -1) {
      lane = laneEnds.length;
    }
    laneEnds[lane] = span.to;
    items.push({ campaign, from: span.from, to: span.to, lane });
  }
  return items;
}

const ITEMS = itemsOfWeek();

const LANE_COUNT = Math.max(...ITEMS.map((item) => item.lane)) + 1;

function todayClassOf(isToday: boolean) {
  if (isToday) {
    return 'bg-primary text-primary-foreground';
  }
  return undefined;
}

function selectedClassOf(isSelected: boolean) {
  if (isSelected) {
    return 'outline-2 outline-offset-2 outline-primary';
  }
  return undefined;
}

function spanWordsOf(item: WeekItem) {
  const first = WEEK[item.from].weekday;
  const last = WEEK[item.to].weekday;
  if (first === last) {
    return first;
  }
  return `${first} to ${last}`;
}

function captionOf(selectedId: string | null) {
  if (selectedId === null) {
    return 'Select a campaign to find it in the table';
  }
  const campaign = campaignOf(selectedId);
  const item = ITEMS.find((candidate) => candidate.campaign.id === selectedId);
  const channel = channelOf(campaign.channel);
  if (!item) {
    return `${campaign.name}, ${channel.name}`;
  }
  return `${campaign.name}, ${channel.name}, ${spanWordsOf(item)}`;
}

type WeekStripProps = {
  selectedId: string | null;
  pressed: string | null;
  onSelect: (id: string) => void;
};

export function WeekStrip({ selectedId, pressed, onSelect }: WeekStripProps) {
  const caption = captionOf(selectedId);

  return (
    <ChartCard
      title='Campaigns this week'
      section='week'
      description={
        <p className='text-muted-foreground text-xs'>{WEEK_RANGE}</p>
      }
    >
      <div className='relative -mx-1 overflow-x-auto px-1'>
        <div
          className='grid min-w-[28rem] grid-cols-7 gap-x-1 gap-y-1'
          style={{ gridTemplateRows: `auto repeat(${LANE_COUNT}, 1.75rem)` }}
        >
          <span
            aria-hidden='true'
            className='bg-foreground/[0.04] rounded-lg'
            style={{
              gridColumn: TODAY_INDEX + 1,
              gridRow: `1 / span ${LANE_COUNT + 1}`,
            }}
          />
          {WEEK.map((day) => {
            const isToday = day.index === TODAY_INDEX;
            return (
              <div
                key={day.index}
                className='text-muted-foreground relative flex flex-col items-center gap-0.5 py-1 text-xs'
                style={{ gridColumn: day.index + 1, gridRow: 1 }}
              >
                <span>{day.weekday}</span>
                <span
                  className={cn(
                    'inline-flex size-6 items-center justify-center rounded-full text-[13px] font-medium tabular-nums',
                    todayClassOf(isToday)
                  )}
                >
                  {day.dayOfMonth}
                </span>
              </div>
            );
          })}
          {ITEMS.map((item) => {
            const { campaign } = item;
            const channel = channelOf(campaign.channel);
            const isSelected = campaign.id === selectedId;
            const isPressed = pressed === `campaign-${campaign.id}`;
            const style: ChipStyle = {
              '--chip': seriesColorOf(channel.series),
              gridColumn: `${item.from + 1} / ${item.to + 2}`,
              gridRow: item.lane + 2,
            };
            return (
              <button
                key={campaign.id}
                type='button'
                aria-pressed={isSelected}
                aria-label={`${campaign.name}, ${channel.name}, ${spanWordsOf(item)}`}
                onClick={() => onSelect(campaign.id)}
                style={style}
                className={cn(
                  'chip-3d focus-visible:outline-ring relative flex h-7 min-w-0 cursor-pointer items-center rounded-md px-2 text-start text-xs font-medium transition-[scale] duration-150 ease-(--ease-out-strong) outline-none focus-visible:outline-2 focus-visible:outline-offset-2 active:scale-[0.97]',
                  selectedClassOf(isSelected),
                  pressedQuietOf(isPressed)
                )}
              >
                <span className='truncate'>{campaign.name}</span>
              </button>
            );
          })}
        </div>
      </div>
      <Swap swapKey={caption} className='text-muted-foreground min-h-5 text-xs'>
        {caption}
      </Swap>
    </ChartCard>
  );
}
